import React from 'react';
import { loginWithGoogle } from '../../services/api';

const Login = () => {
  return (
    <div style={styles.container}>
      <div style={styles.card}>
        <div style={styles.iconContainer}>🍽️</div>

        <h1 style={styles.title}>Welcome Back</h1>
        <p style={styles.subtitle}>Sign in to reserve your perfect dining experience</p>

        <button onClick={loginWithGoogle} style={styles.googleButton}>
          <svg style={styles.googleIcon} viewBox="0 0 24 24">
            <path fill="#4285F4" d="M22.56 12.25c0-.78-.07-1.53-.2-2.25H12v4.26h5.92c-.26 1.37-1.04 2.53-2.21 3.31v2.77h3.57c2.08-1.92 3.28-4.74 3.28-8.09z"/>
            <path fill="#34A853" d="M12 23c2.97 0 5.46-.98 7.28-2.66l-3.57-2.77c-.98.66-2.23 1.06-3.71 1.06-2.86 0-5.29-1.93-6.16-4.53H2.18v2.84C3.99 20.53 7.7 23 12 23z"/>
            <path fill="#FBBC05" d="M5.84 14.09c-.22-.66-.35-1.36-.35-2.09s.13-1.43.35-2.09V7.07H2.18C1.43 8.55 1 10.22 1 12s.43 3.45 1.18 4.93l2.85-2.22.81-.62z"/>
            <path fill="#EA4335" d="M12 5.38c1.62 0 3.06.56 4.21 1.64l3.15-3.15C17.45 2.09 14.97 1 12 1 7.7 1 3.99 3.47 2.18 7.07l3.66 2.84c.87-2.6 3.3-4.53 6.16-4.53z"/>
          </svg>
          Continue with Google
        </button>

        <div style={styles.features}>
          <div style={styles.feature}>
            <span style={styles.featureIcon}>🥗</span>
            <span style={styles.featureText}>Convenience</span>
          </div>
          <div style={styles.feature}>
            <span style={styles.featureIcon}>🔒</span>
            <span style={styles.featureText}>Secure & Safe</span>
          </div>
          <div style={styles.feature}>
            <span style={styles.featureIcon}>🎉</span>
            <span style={styles.featureText}>Best Experience</span>
          </div>
        </div>
      </div>
    </div>
  );
};

const styles = {
  container: {
    display: 'flex',
    justifyContent: 'center',
    alignItems: 'center',
    minHeight: '100vh',
    background: 'linear-gradient(135deg, #667eea, #764ba2)',
    fontFamily: "'Poppins', sans-serif",
  },
  card: {
    background: 'white',
    padding: '3rem 2.5rem',
    borderRadius: '30px',
    boxShadow: '0 20px 50px rgba(0,0,0,0.2)',
    textAlign: 'center',
    maxWidth: '400px',
    width: '100%',
  },
  iconContainer: {
    fontSize: '3rem',
    width: '80px',
    height: '80px',
    margin: '0 auto 2rem',
    display: 'flex',
    alignItems: 'center',
    justifyContent: 'center',
    borderRadius: '50%',
    background: 'linear-gradient(135deg, #ff9a9e, #fad0c4)',
    boxShadow: '0 8px 20px rgba(0,0,0,0.15)',
  },
  title: {
    fontSize: '2rem',
    marginBottom: '0.5rem',
    fontWeight: '700',
    color: '#2d3748',
  },
  subtitle: {
    fontSize: '1rem',
    marginBottom: '2rem',
    color: '#4a5568',
  },
  googleButton: {
    display: 'flex',
    alignItems: 'center',
    justifyContent: 'center',
    gap: '10px',
    width: '100%',
    padding: '1rem',
    border: 'none',
    borderRadius: '12px',
    background: '#f5f5f5',
    fontSize: '1rem',
    fontWeight: '600',
    cursor: 'pointer',
    color: '#2d3748',
    marginBottom: '2rem',
    transition: 'all 0.2s',
  },
  googleButtonHover: {
    background: '#e0e0e0',
  },
  googleIcon: {
    width: '24px',
    height: '24px',
  },
  features: {
    display: 'flex',
    justifyContent: 'space-between',
    fontSize: '0.9rem',
    color: '#4a5568',
  },
  feature: {
    display: 'flex',
    alignItems: 'center',
    gap: '6px',
  },
  featureIcon: {
    fontSize: '1.5rem',
  },
  featureText: {
    fontWeight: '600',
  },
};

export default Login;
